216: 			TokenInfoURL:   f.TokenInfoURL,
217: 			ClientID:       f.ClientID,
218: 			ClientSecret:   f.ClientSecret,
219: 			RevokeURL:      f.RevokeURL,
220: 			QuotaProjectID: f.QuotaProjectID,
221: 			Scopes:         params.Scopes,
