248: // ComputeTokenSource returns a token source that fetches access tokens
249: // from Google Compute Engine (GCE)'s metadata server. It's only valid to use
250: // this token source if your program is running on a GCE instance.
251: // If no account is specified, "default" is used.
252: // If no scopes are specified, a set of default scopes are automatically granted.
253: // Further information about retrieving access tokens from the GCE metadata
254: // server can be found at https://cloud.google.com/compute/docs/authentication.
255: func ComputeTokenSource(account string, scope ...string) oauth2.TokenSource {
256: 	// Refresh 3 minutes and 45 seconds early. The shortest MDS cache is currently 4 minutes, so any
257: 	// refreshes earlier are a waste of compute.
258: 	earlyExpirySecs := 225 * time.Second
259: 	return computeTokenSource(account, earlyExpirySecs, scope...)
260: }
