262: func computeTokenSource(account string, earlyExpiry time.Duration, scope ...string) oauth2.TokenSource {
263: 	return oauth2.ReuseTokenSourceWithExpiry(nil, computeSource{account: account, scopes: scope}, earlyExpiry)
264: }
