271: func (cs computeSource) Token() (*oauth2.Token, error) {
272: 	if !metadata.OnGCE() {
273: 		return nil, errors.New("oauth2/google: can't get a token from the metadata service; not running on GCE")
274: 	}
275: 	acct := cs.account
276: 	if acct == "" {
277: 		acct = "default"
278: 	}
279: 	tokenURI := "instance/service-accounts/" + acct + "/token"
280: 	if len(cs.scopes) > 0 {
281: 		v := url.Values{}
282: 		v.Set("scopes", strings.Join(cs.scopes, ","))
283: 		tokenURI = tokenURI + "?" + v.Encode()
284: 	}
285: 	tokenJSON, err := metadata.Get(tokenURI)
286: 	if err != nil {
287: 		return nil, err
288: 	}
289: 	var res oauth2.Token
290: 	err = json.NewDecoder(strings.NewReader(tokenJSON)).Decode(&res)
291: 	if err != nil {
292: 		return nil, fmt.Errorf("oauth2/google: invalid token JSON from metadata: %v", err)
293: 	}
294: 	if res.ExpiresIn == 0 || res.AccessToken == "" {
295: 		return nil, fmt.Errorf("oauth2/google: incomplete token received from metadata")
296: 	}
297: 	tok := &oauth2.Token{
298: 		AccessToken: res.AccessToken,
299: 		TokenType:   res.TokenType,
300: 		Expiry:      time.Now().Add(time.Duration(res.ExpiresIn) * time.Second),
301: 	}
302: 	// NOTE(cbro): add hidden metadata about where the token is from.
